def lengthOfLIS(nums):
    n = len(nums)
    if n == 0:
        return 0

    # dp[i] = length of longest increasing subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
